/** @param {unknown} path */
function assertPath(path) {
  if (typeof path !== 'string') {
    throw new GlobError('path must be a string');
  }
}

/** @param {number} value a Unicode code point */
function codePointLength(value) {
  return value > 0xffff ? 2 : 1;
}

/** @param {number} value a Unicode code point */
function codePointToString(value) {
  // Unpaired surrogates can occur in ordinary JavaScript strings.
  return value <= 0xffff ? String.fromCharCode(value) : String.fromCodePoint(value);
}

/** @param {number} value a Unicode code point */
function firstCodePoint(text) {
  return text.codePointAt(0);
}

/**
 * Compare two code points, optionally using the case folding exposed by the
 * JavaScript string API.
 */
function codePointsEqual(left, right, nocase) {
  if (left === right) {
    return true;
  }
  if (!nocase) {
    return false;
  }

  const leftText = codePointToString(left);
  const rightText = codePointToString(right);
  return (
    leftText.toLowerCase() === rightText.toLowerCase() ||
    leftText.toUpperCase() === rightText.toUpperCase()
  );
}

/** @param {number} value @param {number} start @param {number} end */
function codePointInRange(value, start, end, nocase) {
  if (!nocase) {
    return value >= start && value <= end;
  }

  const valueText = codePointToString(value);
  const startText = codePointToString(start);
  const endText = codePointToString(end);
  const valueLower = firstCodePoint(valueText.toLowerCase());
  const valueUpper = firstCodePoint(valueText.toUpperCase());
  const startLower = firstCodePoint(startText.toLowerCase());
  const endLower = firstCodePoint(endText.toLowerCase());

  return (
    valueLower >= startLower &&
    valueLower <= endLower &&
    valueUpper >= startLower &&
    valueUpper <= endLower
  );
}

/**
 * Build the literals and ranges in a bracket expression. A hyphen only forms a
 * range when it is unescaped and has usable characters on both sides.
 *
 * @param {{ value: number, escaped: boolean }[]} entries
 */
function buildClassItems(entries) {
  const consumed = new Array(entries.length).fill(false);
  const items = [];

  for (let index = 0; index < entries.length; index += 1) {
    if (consumed[index]) {
      continue;
    }

    const entry = entries[index];
    if (
      entry.value === HYPHEN_CODE &&
      !entry.escaped &&
      index > 0 &&
      index + 1 < entries.length &&
      !consumed[index - 1] &&
      !consumed[index + 1] &&
      entries[index - 1].value <= entries[index + 1].value
    ) {
      items.push({
        type: 'range',
        start: entries[index - 1].value,
        end: entries[index + 1].value,
      });
      consumed[index - 1] = true;
      consumed[index] = true;
      consumed[index + 1] = true;
      continue;
    }

    items.push({ type: 'literal', value: entry.value });
  }

  return items;
}

/**
 * Parse one bracket expression. The returned `next` index points just after
 * its closing bracket.
 *
 * @param {string} pattern
 * @param {number} openIndex
 */
function parseCharacterClass(pattern, openIndex) {
  let index = openIndex + 1;
  let negated = false;

  if (
    index < pattern.length &&
    (pattern[index] === BANG || pattern[index] === CARET)
  ) {
    negated = true;
    index += 1;
  }

  const entries = [];

  // A closing bracket immediately after the opener (or negation mark) is a
  // literal member rather than the end of the expression.
  if (index < pattern.length && pattern[index] === CLOSE_BRACKET) {
    entries.push({ value: CLOSE_BRACKET_CODE, escaped: false });
    index += 1;
  }

  let closed = false;
  while (index < pattern.length) {
    const character = pattern[index];

    if (character === BACKSLASH) {
      if (index + 1 >= pattern.length) {
        throw new GlobError('trailing backslash', index);
      }

      const escapedIndex = index + 1;
      if (pattern[escapedIndex] === SLASH) {
        throw new GlobError('path separator in character class', escapedIndex);
      }

      const value = pattern.codePointAt(escapedIndex);
      entries.push({ value, escaped: true });
      index = escapedIndex + codePointLength(value);
      continue;
    }

    if (character === SLASH) {
      throw new GlobError('path separator in character class', index);
    }

    if (character === CLOSE_BRACKET) {
      closed = true;
      index += 1;
      break;
    }

    const value = pattern.codePointAt(index);
    entries.push({ value, escaped: false });
    index += codePointLength(value);
  }

  if (!closed) {
    throw new GlobError('unterminated character class', openIndex);
  }

  return {
    token: {
      type: 'class',
      class: { negated, items: buildClassItems(entries) },
    },
    next: index,
  };
}

/** @param {{ type: string, value?: number, count?: number, class?: object }[]} tokens */
function makeSegment(tokens) {
  const collapsed = [];
  for (const token of tokens) {
    const previous = collapsed[collapsed.length - 1];
    if (token.type === 'star' && previous && previous.type === 'star') {
      previous.count += token.count;
    } else {
      collapsed.push(token);
    }
  }

  const isGlobstar =
    collapsed.length === 1 &&
    collapsed[0].type === 'star' &&
    collapsed[0].count === 2;

  return {
    globstar: isGlobstar,
    tokens: isGlobstar ? [] : collapsed,
    startsLiteralDot:
      collapsed.length > 0 &&
      collapsed[0].type === 'literal' &&
      collapsed[0].value === DOT_CODE,
  };
}

/**
 * Parse a pattern into segment descriptors. Unescaped slashes separate
 * segments; an escaped slash remains a literal token inside a segment.
 *
 * @param {string} pattern
 */
function parsePattern(pattern) {
  assertPattern(pattern);

  const segments = [];
  let tokens = [];
  let index = 0;

  const flush = () => {
    segments.push(makeSegment(tokens));
    tokens = [];
  };

  while (index < pattern.length) {
    const character = pattern[index];

    if (character === BACKSLASH) {
      if (index + 1 >= pattern.length) {
        throw new GlobError('trailing backslash', index);
      }

      const escapedIndex = index + 1;
      const value = pattern.codePointAt(escapedIndex);
      tokens.push({ type: 'literal', value });
      index = escapedIndex + codePointLength(value);
      continue;
    }

    if (character === SLASH) {
      flush();
      index += 1;
      continue;
    }

    if (character === OPEN_BRACKET) {
      const parsed = parseCharacterClass(pattern, index);
      tokens.push(parsed.token);
      index = parsed.next;
      continue;
    }

    const value = pattern.codePointAt(index);
    if (value === STAR_CODE) {
      const previous = tokens[tokens.length - 1];
      if (previous && previous.type === 'star') {
        previous.count += 1;
      } else {
        tokens.push({ type: 'star', count: 1 });
      }
    } else if (value === QUESTION_CODE) {
      tokens.push({ type: 'question' });
    } else {
      tokens.push({ type: 'literal', value });
    }
    index += codePointLength(value);
  }

  flush();

  // Neighboring whole-segment globstars are one globstar.
  const collapsed = [];
  for (const segment of segments) {
    if (
      segment.globstar &&
      collapsed.length > 0 &&
      collapsed[collapsed.length - 1].globstar
    ) {
      continue;
    }
    collapsed.push(segment);
  }
  return collapsed;
}

/** @param {number} value @param {number} start @param {number} end */
function normalizedRangeContains(value, start, end, nocase) {
  return codePointInRange(value, start, end, nocase);
}

/** @param {object} classExpression @param {number} value @param {boolean} nocase */
function classContains(classExpression, value, nocase) {
  if (value === SLASH_CODE) {
    return false;
  }

  let listed = false;
  for (const item of classExpression.items) {
    if (item.type === 'range') {
      if (normalizedRangeContains(value, item.start, item.end, nocase)) {
        listed = true;
        break;
      }
    } else if (codePointsEqual(item.value, value, nocase)) {
      listed = true;
      break;
    }
  }

  return classExpression.negated ? !listed : listed;
}

/**
 * Match one ordinary pattern segment against one or more path segments. An
 * escaped slash is the only token that can move to the next path segment.
 *
 * @param {object} segment pattern segment descriptor
 * @param {string[]} pathSegments
 * @param {number} startSegment
 * @param {boolean} dot
 * @param {boolean} nocase
 */
function matchSegment(segment, pathSegments, startSegment, dot, nocase) {
  const memo = new Map();

  function visit(tokenIndex, segmentIndex, offset) {
    if (segmentIndex >= pathSegments.length) {
      return [];
    }

    const key = `${tokenIndex}:${segmentIndex}:${offset}`;
    if (memo.has(key)) {
      return memo.get(key);
    }

    const pathSegment = pathSegments[segmentIndex];
    if (
      offset === 0 &&
      !dot &&
      pathSegment.length > 0 &&
      pathSegment.charCodeAt(0) === DOT_CODE &&
      !segment.startsLiteralDot
    ) {
      memo.set(key, []);
      return [];
    }

    let result;
    if (tokenIndex === segment.tokens.length) {
      result = offset === pathSegment.length ? [segmentIndex + 1] : [];
    } else {
      const token = segment.tokens[tokenIndex];
      result = [];

      if (token.type === 'literal') {
        if (token.value === SLASH_CODE) {
          if (offset === pathSegment.length && segmentIndex + 1 < pathSegments.length) {
            result = visit(tokenIndex + 1, segmentIndex + 1, 0);
          }
        } else if (offset < pathSegment.length) {
          const value = pathSegment.codePointAt(offset);
          if (codePointsEqual(token.value, value, nocase)) {
            result = visit(
              tokenIndex + 1,
              segmentIndex,
              offset + codePointLength(value),
            );
          }
        }
      } else if (token.type === 'question') {
        if (offset < pathSegment.length) {
          const value = pathSegment.codePointAt(offset);
          if (value !== SLASH_CODE) {
            result = visit(
              tokenIndex + 1,
              segmentIndex,
              offset + codePointLength(value),
            );
          }
        }
      } else if (token.type === 'class') {
        if (offset < pathSegment.length) {
          const value = pathSegment.codePointAt(offset);
          if (classContains(token.class, value, nocase)) {
            result = visit(
              tokenIndex + 1,
              segmentIndex,
              offset + codePointLength(value),
            );
          }
        }
      } else if (token.type === 'star') {
        let nextOffset = offset;
        result = visit(tokenIndex + 1, segmentIndex, nextOffset);

        while (nextOffset < pathSegment.length) {
          const value = pathSegment.codePointAt(nextOffset);
          nextOffset += codePointLength(value);
          result = result.concat(visit(tokenIndex + 1, segmentIndex, nextOffset));
        }
      }
    }

    memo.set(key, result);
    return result;
  }

  return visit(0, startSegment, 0);
}

/**
 * Return every segment index reachable by a whole-segment globstar.
 *
 * @param {string[]} pathSegments
 * @param {number} startSegment
 * @param {boolean} dot
 */
function globstarEnds(pathSegments, startSegment, dot) {
  const ends = [startSegment];
  let segmentIndex = startSegment;

  while (segmentIndex < pathSegments.length) {
    const pathSegment = pathSegments[segmentIndex];
    if (
      !dot &&
      pathSegment.length > 0 &&
      pathSegment.charCodeAt(0) === DOT_CODE
    ) {
      break;
    }
    segmentIndex += 1;
    ends.push(segmentIndex);
  }

  return ends;
}

/**
 * Match all parsed pattern segments against path segments.
 *
 * @param {object[]} segments
 * @param {string[]} pathSegments
 * @param {boolean} dot
 * @param {boolean} nocase
 */
