  const memo = new Map();

  function visit(segmentIndex, pathSegmentIndex) {
    if (segmentIndex === segments.length) {
      return pathSegmentIndex === pathSegments.length;
    }

    const key = `${segmentIndex}:${pathSegmentIndex}`;
    if (memo.has(key)) {
      return memo.get(key);
    }

    const segment = segments[segmentIndex];
    let ends;
    if (segment.globstar) {
      ends = globstarEnds(pathSegments, pathSegmentIndex, dot);
    } else if (pathSegmentIndex < pathSegments.length) {
      ends = matchSegment(segment, pathSegments, pathSegmentIndex, dot, nocase);
    } else {
      ends = [];
    }

    for (const end of ends) {
      if (visit(segmentIndex + 1, end)) {
        memo.set(key, true);
        return true;
      }
    }

    memo.set(key, false);
    return false;
  }

  return visit(0, 0);
}

